"""Documented SXF Third Moment Research case study enrichment.

Keeps the generated Signal page aligned with the primary OpenAI story and the
SXF editorial analysis after the scheduled feed-generation workflow runs.
"""
from __future__ import annotations
import json
import re

DESCRIPTION = "How Third Moment Research runs 10,000 AI agents for 36–48 hours, cuts backtesting from 3 hours to 3–5 minutes, and manages security with Codex and Daybreak."
SUMMARY = "Third Moment Research says it operates 10,000 concurrent AI agents for 36–48-hour research sessions. Its OpenAI case study reports a 97% backtesting-time reduction after Codex identified caching and memory-packing optimizations; an outer agent harness handles stalled tasks, and Daybreak tests simulation security."
WHY = "The engineering lesson is not simply scale. Faster tool execution reduces status-polling tokens and context noise; an outer supervisor can retry, end or escalate stalled work; and security testing becomes a precondition for wider autonomy. These are separate infrastructure requirements, not proofs that every agent completes its job successfully."
VERIFY = "OpenAI reports customer-supplied results, not an independently audited benchmark. Verify the exact concurrency window, accounting for failed and retried runs, token and compute cost per accepted result, backtest correctness, sandbox escape testing and human escalation rate before comparing the system with alternatives."
SECTION_HTML = "\n<section class=\"signal-deep-dive shell tmr-research\" id=\"third-moment-analysis\" aria-labelledby=\"tmr-title\">\n  <div class=\"intel-section-head\"><div><p class=\"eyebrow\">SXF ORIGINAL ANALYSIS / OCTOBER 18, 2026</p><h2 id=\"tmr-title\">Inside Third Moment's 10,000-agent research system</h2></div><span>Source: OpenAI customer report</span></div>\n  <p class=\"tmr-lead\">Running thousands of agents for days is an infrastructure problem as much as a model capability. Third Moment Research's published case study connects parallel investigations, faster backtesting, supervision, and containment into one operational loop. The numbers below are <strong>reported by OpenAI from the company's experience</strong>, not independently reproduced performance measurements by SXF.</p>\n  <div class=\"tmr-metrics\" aria-label=\"Four figures reported in OpenAI case study\">\n    <div><strong>10,000</strong><span>AI agents operating concurrently</span></div>\n    <div><strong>36–48h</strong><span>Duration of an autonomous research session</span></div>\n    <div><strong>97%</strong><span>Reported reduction in backtest time</span></div>\n    <div><strong>1T</strong><span>OpenAI tokens used in one day</span></div>\n  </div>\n  <div class=\"tmr-content-grid\">\n    <div>\n      <h3>The decisive change: remove the waiting, not just speed up the model</h3>\n      <p>Agents in the quantitative-research environment were repeatedly checking whether lengthy market-data backtests had finished. Those status requests consumed tokens and filled working context without advancing the investigation. According to the OpenAI report, Codex used recorded trajectories and code-level profiling to locate a bottleneck, then introduced caching and memory-packing changes.</p>\n      <p>One backtest went from <strong>roughly three hours to roughly three to five minutes</strong>. That improvement does more than shorten a test: it gives a long-running agent quicker observations and allows the next experiment to be chosen sooner. The reported 97% reduction is specific to this customer workflow; it is not a general speedup figure for AI agents or Codex.</p>\n    </div>\n    <aside class=\"tmr-insight\"><span>ENGINEERING TAKEAWAY 01</span><strong>Optimize the action–observation loop.</strong><p>At large scale, slow tools cause repeated polling, context growth and wasted reasoning budget. Tool latency, cancellation and state management can become as important as the underlying language model.</p></aside>\n  </div>\n  <div class=\"tmr-architecture\" role=\"group\" aria-label=\"Interpretation of the reported agent control loop\">\n    <div><span>01 / EXECUTE</span><strong>Research agent</strong><small>Plans hypotheses, runs experiments and uses Codex tools</small></div>\n    <div><span>02 / OBSERVE</span><strong>Results + trajectory</strong><small>Tracks code, outputs, timing and unfinished work</small></div>\n    <div><span>03 / SUPERVISE</span><strong>Outer harness</strong><small>Retries, terminates or escalates to human review</small></div>\n    <div><span>04 / CONTAIN</span><strong>Security checks</strong><small>Daybreak probes simulation-environment boundaries</small></div>\n  </div>\n  <h3>How the system keeps agents working for 36–48 hours</h3>\n  <p>OpenAI describes a <strong>Codex execution harness inside a containerized research environment</strong> with access to the documentation, code and data relevant to each task. GPT-6 Astra, GPT-6 Sol and GPT-6.1 Sol support reasoning and the research process, while a separate supervisory harness powered by GPT-6 Sol or GPT-6.1 Sol examines interrupted trajectories. It can choose to retry, stop the job or send it for human review rather than assuming an unfinished task is a success.</p>\n  <p>Third Moment also describes finding recurring failure patterns in recorded agent trajectories, creating targeted synthetic cases, and using those cases to improve the system. This makes failure analysis and evaluation design part of the feedback loop. It does <em>not</em> establish that the resulting model is universally self-improving or that a fleet of 10,000 independent runs always succeeds.</p>\n  <div class=\"tmr-content-grid\">\n    <div>\n      <h3>Security is part of the compute pipeline</h3>\n      <p>The company uses <strong>Daybreak</strong> to test whether agents in its simulation environment could escape their sandbox and reach the surrounding network. This matters because an agent allowed to operate for days has more opportunities to encounter malicious inputs, misuse credentials or take unintended actions. A security gate before launch is sensible, but the OpenAI story does not provide public penetration-test pass rates or an independent attestation.</p>\n    </div>\n    <aside class=\"tmr-insight\"><span>ENGINEERING TAKEAWAY 02</span><strong>Autonomy needs an independent stop condition.</strong><p>A long context window alone cannot guarantee task completion. Supervision, scoped permissions, observability and a human escalation path need to sit outside the agent's immediate objective.</p></aside>\n  </div>\n  <h3>Which models are involved?</h3>\n  <p>The report names <a href=\"/models/gpt-6-astra/\">GPT-6 Astra</a>, <a href=\"/models/gpt-6-sol/\">GPT-6 Sol</a> and <a href=\"/models/gpt-6-1-sol/\">GPT-6.1 Sol</a> as reasoning components. It also describes using <a href=\"/models/gpt-5-6/\">GPT-5.6</a> with Codex to diagnose the backtest bottleneck. <strong>Codex is the coding-agent harness, not a substitute name for one of these models.</strong> Third Moment says it evaluates models against its own tasks and values GPT-6.1 Sol's reported token efficiency; those are customer observations, not a cross-provider head-to-head benchmark.</p>\n  <div class=\"tmr-company\">\n    <span>COMPANY PROFILE / FUNDING</span>\n    <h3>What is Third Moment Research, and is its funding public?</h3>\n    <p><a href=\"https://thirdmomentresearch.com/\" target=\"_blank\" rel=\"noopener noreferrer\">Third Moment Research</a> describes an OpenAI-compatible, auto-improving inference service built around collecting execution trajectories, diagnosing recurrent errors and improving models or agent harnesses with targeted evaluations. OpenAI describes it as a North American technology startup.</p>\n    <p><strong>Funding status:</strong> The public company website and OpenAI customer story reviewed on October 18, 2026 did not state a funding-round amount, investor list or announced valuation. This is a statement about those sources, <em>not</em> evidence that the company has raised no capital. We do not assign an unsupported funding figure.</p>\n  </div>\n  <h3>What these numbers do—and do not—demonstrate</h3>\n  <div class=\"tmr-table-wrap\"><table class=\"tmr-evidence-table\"><thead><tr><th scope=\"col\">Reported observation</th><th scope=\"col\">Reasonable interpretation</th><th scope=\"col\">Still unknown</th></tr></thead><tbody>\n   <tr><td>10,000 concurrent agents</td><td>Substantial parallel research throughput</td><td>Job-completion rate and retry-adjusted cost</td></tr>\n   <tr><td>36–48-hour sessions</td><td>Orchestration supports extended work</td><td>How often tasks require human intervention</td></tr>\n   <tr><td>~3 hours to 3–5 minutes</td><td>Backtest optimization removes a workflow bottleneck</td><td>Reproducibility on other workloads and hardware</td></tr>\n   <tr><td>One trillion tokens in a day</td><td>Very high inference volume</td><td>Cost per validated research result</td></tr>\n  </tbody></table></div>\n  <p><strong>SXF assessment:</strong> The distinguishing architecture is a measured feedback loop: agents take actions, tools return observations, external supervision handles failure, and security validation protects the environment. The case is evidence of a reported production-style workflow; it is not proof of general autonomous intelligence or an independently verified success rate. For foundational concepts, read <a href=\"/guides/what-is-agentic-ai/\">what agentic AI is and how the execution loop works</a>, then see the <a href=\"/guides/ai-agent-security/\">AI agent security guide</a> for permission and isolation design.</p>\n  <div class=\"tmr-sources\"><span>PRIMARY-SOURCE VERIFICATION</span><a href=\"https://openai.com/index/third-moment-research/\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI · Third Moment Research customer story ↗</a><a href=\"https://thirdmomentresearch.com/\" target=\"_blank\" rel=\"noopener noreferrer\">Third Moment Research · Official company website ↗</a></div>\n</section>\n"
SOCIAL = "https://sxf.si/assets/og/sxf-ai-social.webp"
MODEL_LINKS = "<a href=\"/models/gpt-6-astra/\">GPT-6 Astra</a><a href=\"/models/gpt-6-1-sol/\">GPT-6.1 Sol</a><a href=\"/models/gpt-6-sol/\">GPT-6 Sol</a><a href=\"/models/gpt-5-6/\">GPT-5.6</a>"


def enrich_third_moment_signal(page: str) -> str:
    if 'id="third-moment-analysis"' in page:
        return page
    for meta in ('name="description"', 'property="og:description"', 'name="twitter:description"'):
        pat = r'(<meta ' + re.escape(meta) + r' content=")[^"]*(" />)'
        page, count = re.subn(pat, lambda m: m.group(1) + DESCRIPTION + m.group(2), page, count=1)
        if count != 1: raise ValueError("Missing Third Moment SEO metadata: " + meta)
    old_card = '<meta name="twitter:card" content="summary" />'
    if old_card not in page: raise ValueError("Missing original Twitter card")
    og = '<meta property="og:image" content="' + SOCIAL + '" />\\n' + \
         '<meta property="og:image:width" content="1200" />\\n' + \
         '<meta property="og:image:height" content="630" />\\n' + \
         '<meta property="og:image:type" content="image/webp" />\\n' + \
         '<meta property="og:image:alt" content="SXF analysis of Third Moment Research and 10,000 long-running AI agents" />\\n' + \
         '<meta name="twitter:image" content="' + SOCIAL + '" />\\n' + \
         '<meta name="twitter:image:alt" content="Third Moment Research: 10,000 concurrent AI agents, 36–48-hour sessions and 97% faster backtests, as reported by OpenAI" />\\n'
    page = page.replace(old_card, og + '<meta name="twitter:card" content="summary_large_image" />', 1)
    match = re.search(r'<script type="application/ld\\+json">([\\s\\S]+?)</script>', page)
    if match is None: raise ValueError("Missing Third Moment JSON-LD")
    data = json.loads(match.group(1))
    wp = next(x for x in data["@graph"] if x["@type"] == "WebPage")
    article = next(x for x in data["@graph"] if x["@type"] == "Article")
    wp["description"] = DESCRIPTION
    wp["primaryImageOfPage"] = {"@type":"ImageObject","url":SOCIAL,"width":1200,"height":630}
    article["description"] = DESCRIPTION
    article["dateModified"] = "2026-10-18"
    article["image"] = [SOCIAL]
    article["keywords"] = ["Third Moment Research","AI agents","10000 AI agents","autonomous research agents","Codex","GPT-6 Astra","GPT-6.1 Sol","agent orchestration","AI agent security"]
    article["citation"] = ["https://openai.com/index/third-moment-research/","https://thirdmomentresearch.com/"]
    article["about"] = {"@type":"Organization","name":"Third Moment Research","url":"https://thirdmomentresearch.com/"}
    article["mentions"] = [{"@type":"SoftwareApplication","name":name,"url":"https://sxf.si/models/" + slug + "/"} for name, slug in (("GPT-6 Astra","gpt-6-astra"),("GPT-6.1 Sol","gpt-6-1-sol"),("GPT-6 Sol","gpt-6-sol"),("GPT-5.6","gpt-5-6"))]
    page = page.replace(match.group(1),json.dumps(data,ensure_ascii=False,separators=(",",":")),1)
    page,n = re.subn(r'<p class="signal-summary">[^<]*</p>',lambda m:'<p class="signal-summary">' + SUMMARY + '</p>',page,count=1)
    if n != 1: raise ValueError("Missing Third Moment summary")
    for label, text in (("WHY IT MATTERS", WHY), ("WHAT TO VERIFY", VERIFY)):
        pat = '<div class="signal-context"><span>' + label + '</span><p>[^<]+</p></div>'
        page,n = re.subn(pat,lambda m,l=label,t=text:'<div class="signal-context"><span>' + l + '</span><p>' + t + '</p></div>',page,count=1)
        if n != 1: raise ValueError("Missing Third Moment editorial section: " + label)
    target = '<section class="signal-taxonomy shell">'
    if target not in page: raise ValueError("Missing Third Moment taxonomy")
    page = page.replace(target,SECTION_HTML + '\\n' + target,1)
    page,n = re.subn(r'<div><span>MODELS</span>[\\s\\S]*?</div>',lambda m:'<div><span>MODELS</span>' + MODEL_LINKS + '</div>',page,count=1)
    if n != 1: raise ValueError("Missing model taxonomy")
    return page
